          cognitiveLevel: 2,
          marks: 4,
          context: 'P(G) = 0.61.',
          prompt: 'Determine P(not G).',
          answer: '0.39',
          explanation: 'P(not G) = 1 − P(G) = 1 − 0.61 = 0.39.',
